class InputComponent {
public:
  virtual ~InputComponent() {}
  virtual void update(GameObject& obj) = 0;
};

class NetworkInput : public InputComponent {
public:
  explicit NetworkInput(PeerId peer) : peer_(peer) {}
  virtual void update(GameObject& obj) {
    InputPacket p = net::latestInput(peer_);
    obj.velocity.x = p.axisX * RUN_SPEED;
    obj.wantsJump = p.jump;
  }
private:
  PeerId peer_;
};

// Player drops: AI takes over; physics/graphics untouched
void onDisconnect(GameObject& obj) { obj.setInput(new BotInput()); }

class Component {
public:
  virtual ~Component() {}
  virtual void receive(int message) = 0;
};

class AudioComponent : public Component {
public:
  virtual void receive(int message) {
    if (message == MSG_LANDED) audio.play(SFX_LAND);
  }
};

class AnimationComponent : public Component {
public:
  explicit AnimationComponent(PhysicsComponent* physics) : physics_(physics) {}
  void update(GameObject& obj) {
    current_ = physics_->isOnGround() ? &idle_ : &jump_;
  }
  virtual void receive(int) {}
private:
  PhysicsComponent* physics_;  // direct reference: closely related pair
  Clip idle_, jump_;
  Clip* current_ = &idle_;
};

// Components stored contiguously, updated per system
struct World {
  std::vector<PhysicsComponent> physics;
  std::vector<AIComponent>      ai;
  std::vector<RenderComponent>  render;

  void update() {
    for (auto& p : physics) p.update();
    for (auto& a : ai)      a.update();
    for (auto& r : render)  r.update();
  }
};

struct Unit {  // just indices into the arrays
  int physicsIndex, aiIndex, renderIndex;
};

using Creator = std::function<Component*(const Json&)>;
std::map<std::string, Creator> componentRegistry;

GameObject* PrefabFactory::create(const Prefab& prefab) {
  GameObject* obj = new GameObject();
  for (const ComponentDesc& d : prefab.components) {
    obj->addComponent(componentRegistry.at(d.type)(d.params));
  }
  // Validate declared dependencies, e.g. Trap requires Physics
  for (Component* c : obj->components()) {
    for (const std::string& dep : c->requires())
      if (!obj->has(dep)) reportError(prefab.name, c->name(), dep);
  }
  return obj;
}
